+}
+
+export function normalizeErrorStackOptions(
+  input: unknown
+): NormalizedErrorStackOptions | undefined {
+  if (typeof input !== 'object' || input === null || Array.isArray(input)) {
+    return undefined;
+  }
+
+  const raw = input as ErrorStackOptions;
+  let mode: ErrorStackMode =
+    raw.mode === 'string' || raw.mode === 'frames' || raw.mode === 'off'
+      ? raw.mode
+      : 'off';
+  const maxStackLines = raw.maxStackLines;
+  if (
+    maxStackLines !== undefined &&
+    (!Number.isInteger(maxStackLines) || maxStackLines <= 0)
+  ) {
+    mode = 'off';
+  }
+
+  let includeCauses: IncludeCauses =
+    raw.includeCauses === 'direct' || raw.includeCauses === 'deep'
+      ? raw.includeCauses
+      : 'none';
+  const maxCauseDepth = raw.maxCauseDepth;
+  if (maxCauseDepth !== undefined && !Number.isInteger(maxCauseDepth)) {
+    includeCauses = 'none';
+  }
+
+  const classFilter = Array.isArray(raw.classFilter)
+    ? raw.classFilter.filter((name): name is string => typeof name === 'string')
+    : typeof raw.classFilter === 'string'
+      ? [raw.classFilter]
+      : undefined;
+
+  return {
