+import { NormalizedErrorStackOptions } from './error-options.js';
+
+export function normalizeStackNewlines(stack: string): string {
+  return stack.replace(/\\r\
?/g, '\
');
+}
+
+function stripFrame(line: string, mode: NormalizedErrorStackOptions['stripInternalFrames']) {
+  const node = line.includes('node:internal');
+  const superjson = /src\\/(transformer|plainer|index)\\.ts/.test(line);
+  return (
+    (mode === 'node' && node) ||
+    (mode === 'superjson' && superjson) ||
+    (mode === 'node_and_superjson' && (node || superjson))
+  );
+}
+
+function redactPath(line: string, mode: NormalizedErrorStackOptions['redactPaths']): string {
+  if (mode === 'strip_cwd') {
+    const cwd = process.cwd().replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');
+    return line.replace(new RegExp(cwd.replace(/\\\\/g, '[\\\\\\\\/]'), 'g'), '');
+  }
+  if (mode === 'basename') {
+    return line.replace(/(?:[A-Za-z]:[\\\\/]|\\/)[^\\s):]+/g, path => {
+      const parts = path.split(/[\\\\/]/);
+      return parts[parts.length - 1];
+    });
+  }
+  return line;
+}
+
+function initialLines(stack: string, options: NormalizedErrorStackOptions): string[] {
+  const value = options.normalizeNewlines ? normalizeStackNewlines(stack) : stack;
+  return value.split(/\
/).map((line, index) =>
+    index > 0 && options.trimLeadingWhitespace ? line.replace(/^\\s+/, '') : line
+  );
+}
+
+export function processStackString(
+  stack: string,
+  options: NormalizedErrorStackOptions
+): string {
+  let lines = initialLines(stack, options).map(line => redactPath(line, options.redactPaths));
+  if (options.maxStackLines !== undefined) lines = lines.slice(0, options.maxStackLines);
+  return lines.filter((line, index) => index === 0 || !stripFrame(line, options.stripInternalFrames)).join('\
');
+}
+
+export function processStackFrames(
+  stack: string,
+  options: NormalizedErrorStackOptions
+): Array<{ raw: string }> {
+  let lines = initialLines(stack, options).filter(
+    (line, index) => index === 0 || !stripFrame(line, options.stripInternalFrames)
+  );
+  lines = lines.map(line => redactPath(line, options.redactPaths));
+  if (options.maxStackLines !== undefined) lines = lines.slice(0, options.maxStackLines);
+  return lines.map(raw => ({ raw }));
+}
