+function matchesErrorClass(error: Error, superJson: SuperJSON): boolean {
+  const filter = superJson.errorStackOptions?.classFilter;
+  return !filter || filter.includes(error.name);
+}
+
+function usesStackMode(
+  error: Error,
+  superJson: SuperJSON
+): 'string' | 'frames' | undefined {
+  const options = superJson.errorStackOptions;
+  if (!options || !matchesErrorClass(error, superJson)) return undefined;
+  return options.mode === 'string' || options.mode === 'frames'
+    ? options.mode
+    : undefined;
+}
+
+function serializeError(error: Error, superJson: SuperJSON): any {
+  const options = superJson.errorStackOptions;
+  const matches = matchesErrorClass(error, superJson);
+  const baseError: any = {
+    name: error.name,
+    message:
+      options?.sanitizeMessage && matches
+        ? sanitizeMessage(error.message)
+        : error.message,
+  };
+  const isAggregate =
+    typeof AggregateError !== 'undefined' && error instanceof AggregateError;
+
+  if (options === undefined) {
+    if ('cause' in error) baseError.cause = (error as any).cause;
+  } else if (
