+import { describe, expect, it } from 'vitest';
+import SuperJSON from './index.js';
+import { normalizeErrorStackOptions } from './error-options.js';
+
+describe('errorStack', () => {
+  it('keeps legacy Error behavior when omitted and disables stacks for off mode', () => {
+    const error = new Error('no stack');
+    const legacy = new SuperJSON();
+    legacy.allowErrorProps('stack');
+    expect((legacy.serialize(error).meta as any).values).toEqual(['Error']);
+
+    const off = new SuperJSON({ errorStack: {} });
+    off.allowErrorProps('stack');
+    expect((off.serialize(error).json as any).stack).toBeUndefined();
+  });
+
+  it('processes string stacks in the specified order', () => {
+    const json = new SuperJSON({
+      errorStack: {
+        mode: 'string',
+        normalizeNewlines: true,
+        maxStackLines: 3,
+        stripInternalFrames: 'node',
+      },
+    });
+    json.allowErrorProps('stack');
+    const error = new Error('boom');
+    error.stack = 'Error: boom\\r\
    at user (/app/a.ts:1)\\r\
    at internal (node:internal/a:1)\\r\
    at later (/app/b.ts:1)';
+    const serialized = json.serialize(error);
+    expect(serialized.meta?.values).toEqual(['Error/stack']);
+    expect((serialized.json as any).stack).toBe('Error: boom\
at user (/app/a.ts:1)');
+  });
+
+  it('serializes frames and restores them through nested containers', () => {
+    const json = new SuperJSON({ errorStack: { mode: 'frames' } });
